import{_ as t,a,o as d,a4 as n}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"List Admin Users","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"List Admin Users","description":"Paginated list of every admin user (back-office account) configured in the store.","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/users?per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 3,\\n      \\"name\\": \\"Admin\\",\\n      \\"email\\": \\"admin@example.com\\",\\n      \\"roleId\\": 1,\\n      \\"roleName\\": \\"Administrator\\",\\n      \\"status\\": 1,\\n      \\"image\\": null,\\n      \\"imageUrl\\": null,\\n      \\"createdAt\\": \\"2026-01-02T17:24:30+00:00\\",\\n      \\"updatedAt\\": \\"2026-06-05T10:40:17+00:00\\"\\n    },\\n    {\\n      \\"id\\": 1919,\\n      \\"name\\": \\"Everette Reilly\\",\\n      \\"email\\": \\"nikita36@gmail.com\\",\\n      \\"roleId\\": 42,\\n      \\"roleName\\": \\"Catalog Manager\\",\\n      \\"status\\": 1,\\n      \\"image\\": null,\\n      \\"imageUrl\\": null,\\n      \\"createdAt\\": \\"2026-05-28T13:36:13+00:00\\",\\n      \\"updatedAt\\": \\"2026-05-28T13:36:13+00:00\\"\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 2,\\n    \\"from\\": 1,\\n    \\"to\\": 2\\n  }\\n}\\n"},{"id":"filtered","title":"Filtered + Sorted","description":"Narrow by name and status, sorted by name ascending. Supplying multiple filters narrows the result (logical AND).","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/users?name=Admin&status=1&sort=name&order=asc&per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 3,\\n      \\"name\\": \\"Admin\\",\\n      \\"email\\": \\"admin@example.com\\",\\n      \\"roleId\\": 1,\\n      \\"roleName\\": \\"Administrator\\",\\n      \\"status\\": 1,\\n      \\"image\\": null,\\n      \\"imageUrl\\": null,\\n      \\"createdAt\\": \\"2026-01-02T17:24:30+00:00\\",\\n      \\"updatedAt\\": \\"2026-06-05T10:40:17+00:00\\"\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/settings/users/list.md","filePath":"api/rest-api/admin/settings/users/list.md","lastUpdated":1783079210000}'),o={name:"api/rest-api/admin/settings/users/list.md"};function r(i,e,s,c,l,m){return d(),a("div",null,e[0]||(e[0]=[n('<h1 id="list-admin-users" tabindex="-1">List Admin Users <a class="header-anchor" href="#list-admin-users" aria-label="Permalink to &quot;List Admin Users&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/settings/users</code></td><td>GET</td></tr></tbody></table><p>Returns every admin user — the back-office accounts that can sign in to the admin panel — in the <code>{ data, meta }</code> envelope. Each row carries its assigned role (<code>roleId</code> / <code>roleName</code>) and active <code>status</code>. The <code>password</code> and <code>api_token</code> values are never returned.</p><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>Page number, 1-based. Default <code>1</code>.</td></tr><tr><td><code>per_page</code></td><td>Items per page. Default <code>10</code>, max <code>50</code>.</td></tr></tbody></table><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Query parameters that narrow the result. Supplying more than one <strong>narrows further</strong> — they combine with logical <strong>AND</strong>. They mirror the admin Users datagrid filters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Match</th><th>Example</th></tr></thead><tbody><tr><td><code>name</code></td><td>Partial (contains).</td><td><code>?name=Admin</code></td></tr><tr><td><code>email</code></td><td>Partial (contains).</td><td><code>?email=@example.com</code></td></tr><tr><td><code>role_id</code></td><td>Exact — the assigned role id.</td><td><code>?role_id=1</code></td></tr><tr><td><code>status</code></td><td>Exact — <code>1</code> (active) or <code>0</code> (inactive).</td><td><code>?status=1</code></td></tr></tbody></table><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Values</th></tr></thead><tbody><tr><td><code>sort</code></td><td><code>id</code> (default), <code>name</code>, <code>email</code></td></tr><tr><td><code>order</code></td><td><code>asc</code>, <code>desc</code> (default <code>desc</code>)</td></tr></tbody></table><p>Both the compound form <code>?sort=name-asc</code> and the split form <code>?sort=name&amp;order=asc</code> are accepted.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>status</code> is <code>1</code> for an active admin (can sign in) and <code>0</code> for a deactivated one.</li><li><code>image</code> is the stored relative avatar path; <code>imageUrl</code> is its fully-qualified public URL. Both are <code>null</code> for admins without an avatar.</li></ul><p>See the <a href="./">Users overview</a> for field meanings and behaviour.</p>',14)]))}const p=t(o,[["render",r]]);export{u as __pageData,p as default};
